_flight_shots_data_rows_seen = 0
def _safe_frame_int(v):
    try:
        return int(float(v))
    except (ValueError, TypeError):
        return None

df = pd.read_csv(io.StringIO(csv_text))
for i, row in df.iterrows():
    csv_row = _flight_shots_data_rows_seen
    _flight_shots_data_rows_seen += 1

    valid_bounce = _safe_frame_int(row.get('valid_bounce'))
    if valid_bounce == 0:
        continue
    
    print(f"flight={row.get('flight_id')} bf={row.get('bounce_frame')} csv_row={csv_row}")
